// components/public/storefront-hero.tsx — Monumental Minimalist Swiss Hero
// Palette: Obsidian Velvet & Soft Alabaster (Linear/Raycast Style)
// 1. Soft Alabaster in Light Mode (#F8F9FA), Obsidian Charcoal (#0D0E12) in Dark Mode
// 2. Monumental condensed architectural headline: PREMIUM DIGITAL PRODUCTS.
// 3. Single authoritative manifesto sentence
// 4. Single primary tactile action: [ Explore 12 Dispensers ↓ ]
// 5. Zero redundant buttons or spotlight widgets

"use client";

import React from "react";
import { motion, useReducedMotion } from "framer-motion";
import { ArrowDown } from "lucide-react";
import { sfx } from "@/src/lib/sound-effects";

export function StorefrontHero() {
  const shouldReduceMotion = useReducedMotion();

  const handleScrollToFloor = (e: React.MouseEvent) => {
    e.preventDefault();
    sfx.playKeypadClick();
    const floor = document.getElementById("floor");
    if (typeof window !== "undefined" && (window as any).__lenis && floor) {
      (window as any).__lenis.scrollTo(floor, { offset: -20, duration: 1.0 });
    } else if (floor) {
      floor.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  return (
    <section
      id="hero"
      aria-label="Storefront introduction"
      className="w-full relative z-20 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto pt-10 pb-16 sm:pt-16 sm:pb-24 lg:pt-24 lg:pb-32 overflow-x-clip"
    >
      <div className="relative z-10 w-full max-w-5xl mx-auto flex flex-col items-center text-center">
        {/* Minimal Tracked Eyebrow (Calibrated for narrow 320px screens) */}
        <motion.div
          initial={shouldReduceMotion ? false : { opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4 }}
          className="text-[9.5px] sm:text-[11px] font-mono tracking-[0.14em] sm:tracking-[0.25em] text-neutral-800 dark:text-neutral-300 font-semibold uppercase select-none mb-3 sm:mb-4 px-2"
        >
          AUTOMATED DIGITAL SHOWROOM &bull; 12 DISPENSERS
        </motion.div>

        {/* Monumental Headline (Fluid responsive scaling down to 320px) */}
        <h1
          className="text-[28px] xs:text-3xl sm:text-6xl md:text-7xl lg:text-8xl xl:text-[96px] leading-[1.04] sm:leading-[1.02] font-black tracking-[-0.03em] text-[#121316] dark:text-[#EDEDF0] uppercase font-sans select-none my-3 sm:my-6 max-w-4xl mx-auto"
        >
          Premium Digital Products.
        </h1>

        {/* Single Authoritative Manifesto */}
        <p
          className="text-xs sm:text-base lg:text-lg text-neutral-800 dark:text-neutral-300 font-medium max-w-xl mx-auto leading-relaxed font-sans mb-6 sm:mb-10 text-center px-2"
        >
          Instant automated delivery for verified software subscriptions, developer tools, and solo credentials. Guaranteed.
        </p>

        {/* Single Authoritative Tactile CTA Button */}
        <motion.div
          initial={shouldReduceMotion ? false : { opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, delay: 0.2 }}
        >
          <a
            href="#floor"
            onClick={handleScrollToFloor}
            className="group inline-flex items-center gap-2.5 sm:gap-3 px-6 py-3.5 sm:px-8 sm:py-4 rounded-xl bg-[#121316] hover:bg-[#20232C] text-[#F8F9FA] dark:bg-[#EDEDF0] dark:hover:bg-[#FFFFFF] dark:text-[#0D0E12] font-sans font-semibold text-xs sm:text-sm shadow-md active:scale-[0.98] transition-transform duration-100 ease-out cursor-pointer select-none focus-visible:ring-2 focus-visible:ring-neutral-400 dark:focus-visible:ring-white/40 focus-visible:outline-none"
          >
            <span>Explore 12 Dispensers</span>
            <ArrowDown className="w-4 h-4 transition-transform duration-200 group-hover:translate-y-0.5" />
          </a>
        </motion.div>
      </div>
    </section>
  );
}

export default StorefrontHero;

